create function escen_private.safe_history_record(p_row escen_private.legacy_rows) returns jsonb
language sql stable set search_path=pg_catalog as $$
  select jsonb_build_object('id',p_row.id,'sourceId',p_row.source_id,'batchId',p_row.batch_id,'status',p_row.status,
    'values',coalesce((select jsonb_object_agg(e.key,e.value) from jsonb_each(p_row.payload) e
      where e.key in (select jsonb_object_keys(c.definition->'fields'))),'{}'),
    'issues',coalesce((select jsonb_agg(distinct i.code) from escen_private.import_issues i where i.row_id=p_row.id and i.resolved_at is null),'[]'))
  from escen_private.history_catalog c where c.table_name=p_row.source_table;
$$;
create function escen_private.history_visible_row(p_row escen_private.legacy_rows) returns boolean
language sql stable set search_path=pg_catalog as $$
  select p_row.source_table not in ('users','role_user') or not exists(
    select 1 from escen_private.source_mappings m left join escen.role_grants g on m.target_table='role_grants' and g.id=m.target_id
    join escen.accounts a on a.id=case when m.target_table='accounts' then m.target_id else g.account_id end
    where m.row_id=p_row.id and m.target_table in ('accounts','role_grants') and a.archived_at is not null);
$$;
create function public.escen_history_catalog() returns jsonb
language sql stable security definer set search_path=pg_catalog as $$
  select jsonb_build_object('totalSourceRows',(select count(*) from escen_private.legacy_rows),
    'datasets',coalesce((select jsonb_agg(jsonb_build_object('table',c.table_name,'count',(select count(*) from escen_private.legacy_rows l where l.source_table=c.table_name and escen_private.history_visible_row(l)),
      'flagged',(select count(*) from escen_private.legacy_rows l where l.source_table=c.table_name and escen_private.history_visible_row(l) and exists(select 1 from escen_private.import_issues i where i.row_id=l.id and i.resolved_at is null)))) from escen_private.history_catalog c),'[]'),
    'references',coalesce((select jsonb_object_agg(c.table_name,coalesce((select jsonb_agg(escen_private.safe_history_record(l)) from escen_private.legacy_rows l where l.source_table=c.table_name and escen_private.history_visible_row(l)),'[]'))
      from escen_private.history_catalog c where c.table_name in ('etudiants','etudiant_group','users','annee_scolaires','niveaux','filieres','groups','matieres','periodes','unite_valeurs','salles','evaluations','frais_etudiants','frais_scolarites','echeanciers','emploi_du_temps','exam_parts')),'{}'));
$$;
create function public.escen_history_page(p_table text,p_offset integer default 0,p_limit integer default 50,p_query text default '',p_flagged boolean default false,p_student_id text default null) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog as $$
declare result jsonb;
begin
  if not exists(select 1 from escen_private.history_catalog where table_name=p_table) then raise exception 'Collection non publiée' using errcode='42501'; end if;
  if p_offset<0 or p_offset>1000000 or p_limit<1 or p_limit>100 or length(p_query)>160 then raise exception 'Pagination invalide' using errcode='23514'; end if;
  with source as (
    select l.*,escen_private.safe_history_record(l) as safe from escen_private.legacy_rows l where l.source_table=p_table and escen_private.history_visible_row(l)
  ), filtered as (
    select * from source where (p_query='' or safe->>'values' ilike '%'||p_query||'%')
      and (not p_flagged or exists(select 1 from escen_private.import_issues i where i.row_id=source.id and i.resolved_at is null))
      and (p_student_id is null or payload->>'etudiant_id'=p_student_id or p_table='etudiants' and source_id=p_student_id)
  ) select jsonb_build_object('table',p_table,'total',(select count(*) from filtered),'offset',p_offset,'limit',p_limit,
    'records',coalesce((select jsonb_agg(page.safe) from (select safe from filtered order by source_id,id offset p_offset limit p_limit) page),'[]')) into result;
  return result;
end $$;
revoke all on function escen_private.history_visible_row(escen_private.legacy_rows) from public;
revoke all on function escen_private.safe_history_record(escen_private.legacy_rows) from public;
revoke all on function public.escen_history_catalog(),public.escen_history_page(text,integer,integer,text,boolean,text) from public;
do $$ declare role_name text; signature text;
begin
  foreach signature in array array['escen_history_catalog()','escen_history_page(text,integer,integer,text,boolean,text)'] loop
    foreach role_name in array array['anon','authenticated'] loop
      if exists(select 1 from pg_roles where rolname=role_name) then execute format('revoke all on function public.%s from %I',signature,role_name); end if;
    end loop;
    if exists(select 1 from pg_roles where rolname='service_role') then execute format('grant execute on function public.%s to service_role',signature); end if;
  end loop;
end $$;
commit;
